package com.lifeos.app.core.database.entity

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * Room entities, schema v1.
 *
 * Conventions (see ARCHITECTURE.md):
 * - Ids: UUID strings generated by [com.lifeos.app.core.domain.Ids].
 * - Instants (createdAt/updatedAt/deletedAt): epoch millis UTC, `Long`.
 * - Local days (dueDate, expenseDate, diaryDate, occurredOn): ISO `yyyy-MM-dd` strings.
 * - Money: `amountMinor` Long + `currencyCode` String — never a float.
 * - Trash: soft delete via `deletedAt`; the Trash screen lists `deletedAt != 0`.
 * - Every table that can be trashed carries `deletedAt`, so restore/forever-delete
 *   is a single, uniform operation.
 */

@Entity(
    tableName = "folders",
    indices = [Index(value = ["parentId"]), Index(value = ["name"])],
)
data class FolderEntity(
    @PrimaryKey val id: String,
    val name: String,
    val parentId: String? = null,
    val sortOrder: Int = 0,
    val createdAt: Long,
    val updatedAt: Long,
    val deletedAt: Long = 0L,
)

@Entity(
    tableName = "tags",
    indices = [Index(value = ["name"], unique = true)],
)
data class TagEntity(
    @PrimaryKey val id: String,
    /** Normalized name — uniqueness is enforced on the normalized form. */
    val name: String,
    val createdAt: Long,
)

/**
 * Join table so a tag can attach to notes, tasks, habits, diary entries and
 * captures without duplicating tag rows.
 */
@Entity(
    tableName = "entity_tags",
    primaryKeys = ["entityType", "entityId", "tagId"],
    indices = [Index(value = ["tagId"]), Index(value = ["entityType", "entityId"])],
)
data class EntityTagCrossRef(
    val entityType: String,
    val entityId: String,
    val tagId: String,
)

@Entity(
    tableName = "notes",
    indices = [
        Index(value = ["folderId"]),
        Index(value = ["updatedAt"]),
        Index(value = ["deletedAt"]),
    ],
)
data class NoteEntity(
    @PrimaryKey val id: String,
    val title: String,
    val body: String,
    /** [com.lifeos.app.core.domain.NoteKind] code. */
    val kind: String = "plain",
    val folderId: String? = null,
    val pinned: Boolean = false,
    val createdAt: Long,
    val updatedAt: Long,
    val deletedAt: Long = 0L,
)

@Entity(
    tableName = "tasks",
    indices = [
        Index(value = ["status"]),
        Index(value = ["dueDate"]),
        Index(value = ["deletedAt"]),
    ],
)
data class TaskEntity(
    @PrimaryKey val id: String,
    val title: String,
    val notes: String = "",
    /** ISO date or null when the task has no due date. */
    val dueDate: String? = null,
    /** [com.lifeos.app.core.domain.Priority] code. */
    val priority: String = "none",
    /** [com.lifeos.app.core.domain.TaskStatus] code. */
    val status: String = "open",
    /** Recurrence id + parameter; see Recurrence.kt. */
    val recurrence: String = "none",
    val recurrenceParameter: String? = null,
    val reminderAt: Long? = null,
    val completedAt: Long? = null,
    val createdAt: Long,
    val updatedAt: Long,
    val deletedAt: Long = 0L,
)

@Entity(
    tableName = "habits",
    indices = [Index(value = ["archivedAt"]), Index(value = ["deletedAt"])],
)
data class HabitEntity(
    @PrimaryKey val id: String,
    val name: String,
    val emoji: String = "",
    val area: String = "personal",
    val recurrence: String = "daily",
    val recurrenceParameter: String? = null,
    /** `binary` (1 per scheduled day) or `count` (target is [targetPerDay]). */
    val mode: String = "binary",
    val targetPerDay: Int = 1,
    val reminderAt: Long? = null,
    val createdAt: Long,
    val updatedAt: Long,
    val archivedAt: Long? = null,
    val deletedAt: Long = 0L,
)

@Entity(
    tableName = "habit_completions",
    primaryKeys = ["habitId", "date"],
    indices = [Index(value = ["date"]), Index(value = ["habitId", "date"])],
)
data class HabitCompletionEntity(
    val habitId: String,
    /** ISO `yyyy-MM-dd` — completion date is *local*, never a timestamp. */
    val date: String,
    /** Completed amount for `count` habits; always >= 1. */
    val amount: Int = 1,
    val note: String = "",
    val recordedAt: Long,
)

@Entity(
    tableName = "expenses",
    indices = [
        Index(value = ["expenseDate"]),
        Index(value = ["category"]),
        Index(value = ["deletedAt"]),
    ],
)
data class ExpenseEntity(
    @PrimaryKey val id: String,
    /** Integer minor units (paise/cents). See Money.kt — never a float. */
    val amountMinor: Long,
    val currencyCode: String,
    val category: String,
    val note: String = "",
    val paymentMethod: String = "",
    val expenseDate: String,
    val createdAt: Long,
    val updatedAt: Long,
    val deletedAt: Long = 0L,
)

@Entity(
    tableName = "diary_entries",
    indices = [Index(value = ["diaryDate"], unique = true), Index(value = ["deletedAt"])],
)
data class DiaryEntryEntity(
    @PrimaryKey val id: String,
    /** ISO date, unique — one entry per day (spec). */
    val diaryDate: String,
    val title: String = "",
    val body: String,
    /** [com.lifeos.app.core.domain.Mood] code, optional. */
    val mood: String? = null,
    val createdAt: Long,
    val updatedAt: Long,
    val deletedAt: Long = 0L,
)

@Entity(
    tableName = "captures",
    indices = [Index(value = ["type"]), Index(value = ["occurredOn"]), Index(value = ["deletedAt"])],
)
data class CaptureEntity(
    @PrimaryKey val id: String,
    /** [com.lifeos.app.core.domain.CaptureType] code. */
    val type: String,
    val text: String = "",
    /** ISO date the capture happened (may differ from createdAt around midnight). */
    val occurredOn: String,
    /** Latitude/longitude, only for LOCATION captures; stored as strings for precision. */
    val latitude: Double? = null,
    val longitude: Double? = null,
    val placeLabel: String? = null,
    /** 1..5 mood value, only for MOOD captures. */
    val moodScore: Int? = null,
    val lifeEventId: String? = null,
    val createdAt: Long,
    val updatedAt: Long,
    val deletedAt: Long = 0L,
)

/**
 * Files attached to notes/captures (photos, videos, audio, PDFs).
 * [relativePath] is inside the app-private files dir; never an absolute path.
 */
@Entity(
    tableName = "attachments",
    indices = [Index(value = ["ownerType", "ownerId"])],
)
data class AttachmentEntity(
    @PrimaryKey val id: String,
    val ownerType: String,
    val ownerId: String,
    /** MIME type, e.g. `image/jpeg`. */
    val mimeType: String,
    val relativePath: String,
    val displayName: String,
    val sizeBytes: Long,
    val createdAt: Long,
    val deletedAt: Long = 0L,
)

/**
 * Timeline entries. Rows are created by the app whenever a real action happens;
 * there is no seeded or fake history anywhere (spec).
 */
@Entity(
    tableName = "life_events",
    indices = [Index(value = ["occurredOn"]), Index(value = ["sourceType", "sourceId"]), Index(value = ["deletedAt"])],
)
data class LifeEventEntity(
    @PrimaryKey val id: String,
    /** [com.lifeos.app.core.domain.LifeEventType] code. */
    val type: String,
    val title: String,
    val detail: String = "",
    val area: String = "personal",
    /** ISO date used for timeline grouping. */
    val occurredOn: String,
    val occurredAt: Long,
    /** The entity that caused this event (notes.id, tasks.id, …), nullable. */
    val sourceType: String? = null,
    val sourceId: String? = null,
    val deletedAt: Long = 0L,
)
